import pandas as pd
from joblib import Parallel, delayed

def calculate_difference(row):
    return row['accel_stats_z_p99'] - row['accel_stats_z_p1']

def parallel_calculate_differences(df):
    return Parallel(n_jobs=-1)(delayed(calculate_difference)(row) for index, row in df.iterrows())

def find_largest_diff_location(df):
    df['difference'] = parallel_calculate_differences(df)
    max_diff_row = df.loc[df['difference'].idxmax()]
    return max_diff_row['latitude'], max_diff_row['longitude']

def main():
    result = find_largest_diff_location(df)
    print(result)

